TLM.f("Sancti/08-09",{"officium":"S. Joannis Mariæ Vianney Confessoris","rule":["vide C5;","Gloria"],"fallback":"Commune/C5","from":{"Introitus":"Commune/C5","Lectio":"Commune/C5","Graduale":"Commune/C5","GradualeP":"Commune/C5","Tractus":"Commune/C5","Evangelium":"Commune/C5","Offertorium":"Commune/C5","Communio":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 36:1"},{"k":"text","la":"Noli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Omnípotens et miséricors Deus, qui sanctum Joánnem Maríam pastoráli stúdio et jugi oratiónis ac pœniténtiæ ardóre mirábilem effecísti: da, quǽsumus; ut, ejus exémplo et intercessióne, ánimas fratrum lucrári Christo, et cum eis ætérnam glóriam cónsequi valeámus."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 31:8-11"},{"k":"text","la":"Beátus vir, qui invéntus est sine mácula, et qui post aurum non ábiit, nec sperávit in pecúnia et thesáuris. Quis est hic, et laudábimus eum? fecit enim mirabília in vita sua. Qui probátus est in illo, et perféctus est, erit illi glória ætérna: qui potuit tránsgredi, et non est transgréssus: fácere mala, et non fecit: ídeo stabilíta sunt bona illíus in Dómino, et eleemósynas illíus enarrábit omnis ecclésia sanctórum."}],"Graduale":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja"},{"k":"ref","la":"Ja 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:35-40"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Sint lumbi vestri præcíncti, et lucernæ ardéntes in mánibus vestris, et vos símiles homínibus exspectántibus dóminum suum, quando revertátur a núptiis: ut, cum vénerit et pulsáverit, conféstim apériant ei. Beáti servi illi, quos, cum vénerit dóminus, invénerit vigilántes: amen, dico vobis, quod præcínget se, et fáciet illos discúmbere, et tránsiens ministrábit illis. Et si vénerit in secúnda vigília, et si in tértia vigília vénerit, et ita invénerit, beáti sunt servi illi. Hoc autem scitóte, quóniam, si sciret paterfamílias, qua hora fur veníret, vigiláret útique, et non síneret pérfodi domum suam. Et vos estóte paráti, quia, qua hora non putátis, Fílius hóminis véniet."}],"Offertorium":[{"k":"ref","la":"Ps 88:25"},{"k":"text","la":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Laudis tibi, Dómine, hóstias immolámus in tuórum commemoratióne Sanctórum: quibus nos et præséntibus éxui malis confídimus et futúris."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 24:46-47"},{"k":"text","la":"Beátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Refécti cibo potúque cœlésti, Deus noster, te súpplices exorámus: ut, in cujus hæc commemoratióne percépimus, ejus muniámur et précibus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"52236fd7918c9b03":{"t":"Ps 36, 30-31, Ps 36, 1\n(Ps 36, 30-31) Pravednikova usta govore mudrost i jezik njegov kazuje pravdu. Zakon je Božji u srcu njegovu. (Ps 36, 1) Ne zaviđaj sreći grešnika i ne žesti se radi zlotvora.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 36, 30-31) Pravednikova usta govore mudrost i jezik njegov kazuje pravdu. Zakon je Božji u srcu njegovu.","kn":"(Ps. 36, 30, 31). Pravednikova usta govore mudrost i njegov jezik kazuje pravdu. Zakon je Božji u njegovu srcu i njegove noge ne će posrnuti. (Aleluja, Aleluja.) (Ps. 36, 1). Ne zaviđaj sreći ^rješnika i zlotvora! Slava Ocu. Pravednikova.","knRef":"Kniewald 1942, str. 814–815 (snimka 408) (OCR)"},"09f8fdb124784d5d":{"t":"<i>Pomolimo se</i>.\nSvemogući i milosrdni Bože, koji si svetog Ivana Mariju odlikovao izvanrednom dušobrižničkom revnošću i neprestanim žarom u molitvi i pokori, daj, molimo, da po njegovu primjeru i zagovoru uzmognemo osvajati duše naše braće za Krista i s njima postići vječnu slavu.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Svemogući i milosrdni Bože, koji si svetog Ivana Mariju divno uresio revnošću za duše, neprestanom ljubavlju k molitvi i duhom pokore, udijeli nam, molimo Te, snagu, njegovim, zagovorom i primjerom, da duše naših bližnjih predo- bivamo za Krista i s njima zajedno stignemo u blaženu ■ vječnost, po istom G. n.","knRef":"Kniewald 1942, str. 672–673 (snimka 337) (OCR)"},"d0743eab00685bfc":{"t":"Sir 31, 8-11\nČitanje knjige Mudrosti. Blago čovjeku koji se nađe bez ljage i ne teži za zlatom, niti se uzda u novac i blago. Tko je taj, da ga pohvalimo? U svojem je životu učinio divna djela. Tko je u tome prokušan i savršen bit će uvijek slavan. Mogao je sagriješiti, ali nije sagriješio, učiniti zlo, ali nije počinio. Zato priznaje njegova djela Gospodin, a njegovih će se milostinja sjećati sve skupine svetih.","kn":"Čitanje Knjige mudrosti (Crkv. 31, 8-11). Blago čovjeku, koji se našao bez ljage i koji ne ide za zlatom niti se uzda u novac i blago. Tko je taj, da ga hvalimo? Jer je u svom životu učinio divna djela. Vječno će biti slavan, koji je u tom prokušan i savršen; mogao je sagriješiti, a nije sagriješio, i učiniti zlo, a nije učinio. Zato su njegova dobra priznata od Gospodina, i njegove će milostinje kazivati čitav zbor svetih. t!82","knRef":"Kniewald 1942, str. 680–681 (snimka 341) (OCR)"},"929d73ef8c983301":{"t":"Ps 91, 13-14, Ps 91, 3\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik u domu Gospodnjem. (Ps 91, 3) Jutrom naviješta milosrđe tvoje i noću tvoju vjernost.\n\nJak 1, 12\n<i>Aleluja</i>, <i>aleluja</i>.\nBlago čovjeku koji nadvlada napast, jer kad bude prokušan, primit će krunu života. <i>Aleluja</i>.","kn":"(Ps. 91, 13, 14). Pravednik i’aste poput paome i libanonskog cedra u domu Gospodnjem. Ra.no jutrom naviješta Tvoje milosrđe i noću Tvoju vjernost.\n\nAleluja, aleiuja. (Jak. 1, 12) Blago čovjeku, koji pretrpi napast, jer će primiti vijenac slave, kad bude prokušan, aleluja.","knRef":"Kniewald 1942, str. 786–787 (snimka 394) (OCR)"},"52bdf7255321563a":{"t":"Lk 12, 35-40\nSlijedi sveto Evanđelje po Luki. U ono vrijeme Isus reče svojim učenicima: Neka budu opasani vaši bokovi i upaljene svjetiljke u vašim rukama, a vi budite slični slugama koji očekuju svojega gospodara, kada se vraća sa svadbe, da mu smjesta otvore vrata, čim dođe i pokuca. Blago onim slugama koje gospodar kada dođe nađe budne! Uvjeravam vas, da će se sam pripasati, narediti im da sjednu za stol i poslužiti ih. Blago tim slugama, ako ih nađe tako došao on bilo o drugoj, ili o trećoj straži. Pazite: Kada bi domaćin znao u koji čas dolazi tat, ne bi dopustio potkopati svoje kuće. Zato budite pripravni i vi, jer će Čovječji Sin doći u čas, kada vi i ne slutite.","kn":"t Slijedi sveto evanđelje po Luki (12, 35-40). U ono vrijeme reče Isus svojim učenicima: Neka budu opasani vaši bokovi i upaljene svjetiljke u vašim rukama. A vi sami budite kao oni ljudi, koji očekuju svoga gospodara, kad se vraća sa svadbe, da čim dođe i pokuca, smjesta mu otvore vrata. Blago onim slugama, koje gospodar došav nađe budne. Zaista vam kažem, da će se sam priipasati i posaditi Ih za stol i sam će ih poslužiti. Blago tim slugama, ako ih zateče tako, ako dođe o drugoj ili trećoj straži. Znajte ovo: Kad bi domaćin znao, u koji čas dolazi tat, zaista bi bdio i ne bi dao potkopati svoje kuće. I vi budite spremni, jer u čas, kad vi ne mislite, doći će Sin čovječji.","knRef":"Kniewald 1942, str. 594–595 (snimka 298) (OCR)"},"88bea9a296c140ac":{"t":"Ps 88, 25\nMoja će vjernost i moje milosrđe biti s njime, i svojim ću imenom uzdići njegovu moć.","kn":"(Ps. 88, 25). Istina je moja i milosrđe moje B njime i u ime će se moje uzdići moć njegova.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"18a58d3552d982fb":{"t":"Posvećujemo ti, Gospodine, žrtve hvale na spomen tvojih svetih i uzdamo se da ćeš nas po njima izbaviti od sadašnjih i od budućih zala.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Prikazujemo Ti, Gospodine, žrtve hvale spominjući se Tvojih svetih i uzdajućl se, da će nas oni osloboditi i sadašnjih i budućih zala, po G. n.","knRef":"Kniewald 1942, str. 476–477 (snimka 239) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"56842ed674d6e163":{"t":"Mt 24, 46-47\nBlago slugi koga gospodar nađe budna, kad dođe. Zaista vam kažem: Postavit će ga nad svim imanjem svojim.","kn":"(Mt. 24, 46-47). Blago onomu slugi, koga nađe njegov gospodar budna, kad dođe! zaista vam kažem, da će ga postaviti nad svim imanjem svojim.","knRef":"Kniewald 1942, str. 816–817 (snimka 409) (OCR)"},"77eef81bf0c58a4e":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni nebeskim jelom i pićem ponizno te molimo, Bože naš, da budemo zaštićeni molitvama onoga na čiji smo to spomen primili.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Okrijepljeni :nebeskom hranom i pićem, ponizno Te molimo; Bože naš, da nas zaštite molitve onoga, kojega se spominjemo primajući Tvoje darove. Po G. n.","knRef":"Kniewald 1942, str. 476–477 (snimka 239) (OCR)"}},"variants":{"paschal":{"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja"},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}]}}});
